package com.portfolio.assetory.refund;
import java.math.*;import java.time.*;import com.portfolio.assetory.order.domain.OrderItem;import jakarta.persistence.*;
@Entity @Table(name="refunds") public class Refund{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@OneToOne(fetch=FetchType.LAZY)@JoinColumn(name="order_item_id",nullable=false,unique=true)private OrderItem orderItem;@Column(nullable=false,precision=15,scale=2)private BigDecimal refundAmount;@Column(nullable=false,columnDefinition="TEXT")private String reason;@Enumerated(EnumType.STRING)@Column(nullable=false)private RefundStatus status;@Column(nullable=false,updatable=false)private LocalDateTime requestedAt;private LocalDateTime canceledAt;private LocalDateTime processedAt;private LocalDateTime completedAt;private String sellerMessage;private String rejectionReason;protected Refund(){}public static Refund request(OrderItem item,String reason){Refund r=new Refund();r.orderItem=item;r.refundAmount=item.getUnitPrice();r.reason=reason;r.status=RefundStatus.REQUESTED;return r;}@PrePersist void create(){requestedAt=LocalDateTime.now();}public void cancel(){status=RefundStatus.CANCELED;canceledAt=LocalDateTime.now();}public void approve(String m){status=RefundStatus.APPROVED;sellerMessage=m;processedAt=LocalDateTime.now();}public void reject(String m){status=RefundStatus.REJECTED;rejectionReason=m;processedAt=LocalDateTime.now();}public void complete(){status=RefundStatus.COMPLETED;completedAt=LocalDateTime.now();}public Long getId(){return id;}public OrderItem getOrderItem(){return orderItem;}public BigDecimal getRefundAmount(){return refundAmount;}public String getReason(){return reason;}public RefundStatus getStatus(){return status;}public LocalDateTime getRequestedAt(){return requestedAt;}public LocalDateTime getCanceledAt(){return canceledAt;}}
